head.script:
scwin.gPrtdepoId; // PRTDEPO_ID
scwin.gIsurCd; // ISUR_CD
scwin.seq; // 일련번호
scwin.gPrtdepoEndDd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        const fParent = $c.frame.path("../");
        scwin.gIsurCd = fParent.fn_getId();
        scwin.gPrtdepoEndDd = fParent.fn_getPrtdepoEndDd();

        // alert("gIsurCd=" + gIsurCd + " gPrtdepoEndDd=" + gPrtdepoEndDd);

        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40208.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40208.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    // alert("rowCnt-->"+rowcount);

    // alert("dts_List.CountRow-->"+dts_List.CountRow);

};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_close_onclick = function() {
    try {
        self.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40208.btn_close_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        const options = {
            id: "ULDSTF40209",
            title: "의무보유 수정",
            type: "browserPopup",
            width: "830px",
            height: "430px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstmgt/ULDSTF40209.gfm", options);
        scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40208.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_input_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_input_onclick = async function() {
    try {
        scwin.gPrtdepoId = "input";
        const options = {
            id: "ULDSTF40209",
            title: "의무보유 수정",
            type: "browserPopup",
            width: "830px",
            height: "430px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstmgt/ULDSTF40209.gfm", options);
        scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40208.btn_input_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listSync
 * @description 데이타 가져와서 뿌리기 List
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    // alert("보호예수ID(PRTDEPO_ID) : gIsurCd-->"+gIsurCd);

    const url = "/listingCommon.do?SCREN_ID=" + "ULDSTF40208.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=PROTECTED_DEPOSITION_ADMINISTRATIVE_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.prtdepomgt.prtdepo_rto_adm_dtl" + "&{P}param01=" + scwin.gIsurCd + //
        "&{P}param02=" + scwin.gPrtdepoEndDd; //

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};

/**
 * @method
 * @name setSeq
 * @description 조치일련번호 Set
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setSeq = function(obj) {
    scwin.seq = dts_List.getCellData(Number(obj), "SEQ");
};

/**
 * @method
 * @name getSeq
 * @description 조치일련번호 Get
 * @returns {void}
 * @hidden N
 */
scwin.getSeq = function() {
    return scwin.seq;
};

/**
 * @method
 * @name setId
 * @description 보호예수ID Set
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setId = function(obj) {
    scwin.gIsurCd = dts_List.getCellData(Number(obj), "PRTDEPO_ID");
};

/**
 * @method
 * @name getId
 * @description 조치일련번호 Get
 * @returns {void}
 * @hidden N
 */
scwin.getId = function() {
    return scwin.gIsurCd;
};

/**
 * @method
 * @name setPrtdepoId
 * @description set Prtdepo Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setPrtdepoId = function(obj) {
    scwin.gPrtdepoId = dts_List.getCellData(Number(obj), "PRTDEPO_ID");
};

/**
 * @method
 * @name getPrtdepoId
 * @description get Prtdepo Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.getPrtdepoId = function() {
    return scwin.gPrtdepoId;
};
